q2:
SELECT DISTINCT *
FROM (
  SELECT * FROM R AS X WHERE X.X > 50
  UNION ALL
  SELECT * FROM R AS Y WHERE Y.X < 200
) AS T;

SELECT * FROM R1 AS X, R2 AS Y
UNION ALL
SELECT * FROM R1 AS X, R3 AS Y;

schema:
CREATE TABLE R1 (X INT);
CREATE TABLE R2 (X INT);
CREATE TABLE R3 (X INT);

q2:
SELECT * FROM R AS X
UNION ALL
SELECT * FROM S AS Y;

