INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (3, 300, 10, 0);

-- Student 1: two identical SECTION rows cause COUNT > 1 but SUM = 0 in the inner subquery
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (1, 101, 1, 2020, NULL);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (101, 1, 2020, 1, 1, 0);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (101, 1, 2020, 1, 1, 0);

-- Student 2: single SECTION row with TIME_SLOT_ID > 1 makes SUM > 1 but COUNT = 1 in the inner subquery
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (2, 102, 1, 2021, NULL);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (102, 1, 2021, 1, 1, 5);

